pub fn print_hex_char_line(char_hex: i8) {
    let byte = char_hex as u8;
    let high = (byte >> 4) & 0xfu8;
    let low = byte & 0xfu8;
    output_hex_digit(high);
    output_hex_digit(low);
    crate::ffi::put_byte(b'\n');
}

fn output_hex_digit(digit: u8) {
    if digit < 10 {
        crate::ffi::put_byte(b'0' + digit);
    } else {
        crate::ffi::put_byte(b'a' + (digit - 10));
    }
}

pub fn driver(data: i8) {
    let result = data.wrapping_add(1);
    print_hex_char_line(result);
}
